export function searchCategoryIcons(query: string = '', groupFilter?: string): CategoryIconDefinition[] {
  const q = query.trim().toLowerCase();
  return CATEGORY_ICONS_LIST.filter(item => {
    if (groupFilter && groupFilter !== 'all' && item.category !== groupFilter) {
      return false;
    }
    if (!q) return true;
    return (
      item.name.toLowerCase().includes(q) ||
      item.label_fr.toLowerCase().includes(q) ||
      item.label_en.toLowerCase().includes(q)
    );
  });
}

export function findCategoryIcon(name: string): CategoryIconDefinition | undefined {
  return CATEGORY_ICONS_LIST.find(ic => ic.name.toLowerCase() === (name || '').toLowerCase());
}

export function getCategoryVideoPreset(idOrUrl: string): CategoryVideoPreset | undefined {
  if (!idOrUrl) return undefined;
  const clean = idOrUrl.toLowerCase();
  return PRESET_CATEGORY_VIDEOS.find(p => p.id === clean || p.url.toLowerCase() === clean || p.mp4Url.toLowerCase() === clean);
}
